package com.company.skillplatform.artifact.infrastructure.entity;
import com.company.skillplatform.common.infrastructure.entity.BaseJpaEntity;import com.company.skillplatform.compatibility.infrastructure.entity.PlatformEntity;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import jakarta.persistence.*;
@Entity@Table(name="skill_artifact")public class SkillArtifactEntity extends BaseJpaEntity{
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="skill_version_id")private SkillVersionEntity version;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="platform_id")private PlatformEntity platform;@Column(name="os_type",nullable=false,length=32)private String osType;@Column(name="artifact_type",nullable=false,length=32)private String artifactType;@Column(name="object_key",nullable=false,length=512)private String objectKey;@Column(name="file_name",nullable=false,length=255)private String fileName;@Column(name="size_bytes",nullable=false)private long sizeBytes;@Column(nullable=false,length=64)private String sha256;@Column(name="adapter_version",nullable=false,length=64)private String adapterVersion;@Column(name="build_task_id")private Long buildTaskId;@Column(nullable=false,length=32)private String status;
 protected SkillArtifactEntity(){}public SkillArtifactEntity(SkillVersionEntity v,PlatformEntity p,String os,String type,String key,String name,long size,String hash,String adapter,Long task){version=v;platform=p;osType=os;artifactType=type;objectKey=key;fileName=name;sizeBytes=size;sha256=hash;adapterVersion=adapter;buildTaskId=task;status="AVAILABLE";}public SkillVersionEntity getVersion(){return version;}public PlatformEntity getPlatform(){return platform;}public String getOsType(){return osType;}public String getArtifactType(){return artifactType;}public String getObjectKey(){return objectKey;}public String getFileName(){return fileName;}public long getSizeBytes(){return sizeBytes;}public String getSha256(){return sha256;}public String getAdapterVersion(){return adapterVersion;}public String getStatus(){return status;}}
